/* キュアホイップ（ユーザー提供の立ち絵から 切り抜いた パーツ を 関節で 動かす） */
(function(){
const PARTS = [{"n": "hairBackL", "x": 45, "y": 141, "w": 156, "h": 196, "px": 155, "py": 79, "src": "data:image/png;base64,"}, {"n": "hairBackR", "x": 334, "y": 138, "w": 162, "h": 165, "px": 6, "py": 82, "src": "data:image/png;base64,"}, {"n": "tailL", "x": 22, "y": 285, "w": 241, "h": 412, "px": 178, "py": 15, "src": "data:image/png;base64,"}, {"n": "tailR", "x": 290, "y": 288, "w": 207, "h": 383, "px": 50, "py": 12, "src": "data:image/png;base64,"}, {"n": "legUL", "x": 88, "y": 650, "w": 153, "h": 172, "px": 112, "py": 0, "src": "data:image/png;base64,"}, {"n": "legUR", "x": 290, "y": 650, "w": 150, "h": 172, "px": 45, "py": 0, "src": "data:image/png;base64,"}, {"n": "legDL", "x": 91, "y": 800, "w": 102, "h": 245, "px": 81, "py": 0, "src": "data:image/png;base64,"}, {"n": "legDR", "x": 350, "y": 800, "w": 125, "h": 245, "px": 42, "py": 0, "src": "data:image/png;base64,"}, {"n": "skirt", "x": 78, "y": 520, "w": 378, "h": 153, "px": 187, "py": 40, "src": "data:image/png;base64,"}, {"n": "torso", "x": 150, "y": 336, "w": 233, "h": 210, "px": 115, "py": 164, "src": "data:image/png;base64,"}, {"n": "armL", "x": 12, "y": 420, "w": 178, "h": 221, "px": 153, "py": 10, "src": "data:image/png;base64,"}, {"n": "armR", "x": 341, "y": 420, "w": 160, "h": 193, "px": 29, "py": 10, "src": "data:image/png;base64,"}, {"n": "head", "x": 126, "y": 15, "w": 297, "h": 364, "px": 144, "py": 357, "src": "data:image/png;base64,"}];
const _st = document.createElement("style"); _st.textContent = ".wh-stage{position:absolute;inset:0;pointer-events:none}.wh-inner{position:absolute;left:0;top:0;width:540px;height:1045px;transform-origin:0 0}"; document.head.append(_st);
// Cure Whip rig: flat parts + parent links (calf follows thigh). Each part = container div (its own pivot) + image.
(function(global){
  const PARENT = {legDL:'legUL', legDR:'legUR'};
  function create(parts, wrap){
    const by = Object.fromEntries(parts.map(p => [p.n, p]));
    const root = document.createElement('div');
    root.style.cssText = 'position:absolute;left:0;top:0;width:540px;height:1045px;transform-origin:270px 1000px';
    wrap.append(root);
    const els = {};
    for(const p of parts){            // parents are listed before children in ORDER
      const host = PARENT[p.n] ? els[PARENT[p.n]] : root;
      const ox = PARENT[p.n] ? p.x - by[PARENT[p.n]].x : p.x, oy = PARENT[p.n] ? p.y - by[PARENT[p.n]].y : p.y;
      const d = document.createElement('div');
      d.style.cssText = `position:absolute;left:${ox}px;top:${oy}px;width:${p.w}px;height:${p.h}px;transform-origin:${p.px}px ${p.py}px`;
      const img = document.createElement('img');
      img.src = p.src; img.alt = '';
      img.style.cssText = 'position:absolute;left:0;top:0;width:100%;height:100%;max-width:none;pointer-events:none;user-select:none;display:block';
      d.append(img); host.append(d); els[p.n] = d;
    }
    return {
      setRoot(q){ root.style.transform = `translate(${q.dx||0}px,${q.dy||0}px) scale(${q.sx??1},${q.sy??1})`; },
      set(pose){
        for(const n in els){
          const q = pose[n] || {};
          els[n].style.transform = `translate(${q.dx||0}px,${q.dy||0}px) rotate(${q.r||0}deg) scale(${q.sx??1},${q.sy??1})`;
        }
      },
      els
    };
  }
  global.WhipRig = { create };
})(window);

// Cure Whip motions. Each returns {root:{dx,dy,sx,sy}, p:{part:{r,dx,dy,sx,sy}}}; t in seconds.
window.WhipMotions = (function(){
  const S = Math.sin, C = Math.cos, PI = Math.PI, TAU = 2 * PI;
  const ease = x => { x = Math.max(0, Math.min(1, x)); return x * x * (3 - 2 * x); };
  // 片足を 太もも＋すね で 同じ 角度に 動かす（ひざは 後で 少し 曲げる）
  const legs = (l, r, bendL = 0, bendR = 0) => ({
    legUL:{r:l}, legDL:{r:l + bendL}, legUR:{r:r}, legDR:{r:r + bendR}
  });
  const merge = (...objs) => Object.assign({}, ...objs);
  return {
    idle(t){
      const w = TAU / 2.8, b = S(t * w);
      return {root:{dy:-1.5 * b}, p:merge(
        {torso:{dy:-1 * b, sy:1 + .005 * b}, skirt:{sy:1 + .004 * b}, head:{r:1.4 * S(t * w + .6)}},
        {tailL:{r:2 * S(t * w + 1)}, tailR:{r:-2 * S(t * w + 1)}, hairBackL:{r:1.2 * S(t * w + 1)}, hairBackR:{r:-1.2 * S(t * w + 1)}},
        {armL:{r:1.2 * S(t * w)}, armR:{r:-1.2 * S(t * w)}}, legs(0, 0))};
    },
    wave(t){
      const k = ease(t / .6), w = S(t * TAU / .6);
      return {root:{}, p:merge(
        {armR:{r:k * (-118 + 10 * w)}, head:{r:2.5 * S(t * TAU / 1.8)}, torso:{r:1.2 * S(t * TAU / 1.8)}},
        {tailL:{r:2 * S(t * TAU / 1.8)}, tailR:{r:-2 * S(t * TAU / 1.8)}, armL:{r:-1.5}}, legs(0, 0))};
    },
    dance(t){
      const ph = t * TAU / 1.0, s = S(ph), bounce = Math.abs(S(ph / 2));
      return {root:{dy:-12 * bounce}, p:merge(
        {torso:{r:2.5 * S(ph / 2)}, head:{r:-3.5 * S(ph / 2)}, skirt:{r:1.5 * S(ph / 2)}},
        {armL:{r:13 * S(ph / 2)}, armR:{r:-13 * S(ph / 2)}},
        {tailL:{r:6 * S(ph / 2 + 1)}, tailR:{r:-6 * S(ph / 2 + 1)}, hairBackL:{r:3 * S(ph / 2 + 1)}, hairBackR:{r:-3 * S(ph / 2 + 1)}},
        legs(5 * S(ph / 2), -5 * S(ph / 2), 6 * Math.max(0, -s), 6 * Math.max(0, s)))};
    },
    jump(t){
      const T = 1.2, u = (t % T) / T, air = S(PI * Math.min(1, u * 1.3)) * (u < .77 ? 1 : 0);
      const squash = u < .1 ? 1 - .05 * S(u / .1 * PI) : 1;
      return {root:{dy:-100 * air}, p:merge(
        {skirt:{sy:squash}, head:{r:-2.5 * air}, torso:{sy:squash}},
        {armL:{r:-30 * air}, armR:{r:30 * air}, tailL:{r:8 * air}, tailR:{r:-8 * air}},
        legs(8 * air, -8 * air, 10 * air, 10 * air))};
    },
    twirl(t){
      const th = t * TAU / 1.6, c = C(th), k = .72 + .28 * Math.abs(c);
      return {root:{}, p:merge(
        {skirt:{sx:k}, head:{r:3 * S(th)}, torso:{r:2 * S(th)}},
        {tailL:{r:6 * S(th), sx:.94}, tailR:{r:-6 * S(th), sx:.94}},
        {armL:{r:8 * S(th)}, armR:{r:-8 * S(th)}}, legs(0, 0))};
    },
    pose(t){
      const k = ease(t / .6) * (t > 1.6 ? 1 - ease((t - 1.6) / .5) : 1), b = S(t * TAU / 1.4) * .4 + .6;
      return {root:{dy:-4 * k}, p:merge(
        {torso:{r:-3 * k}, head:{r:-7 * k}, armL:{r:-35 * k * b}, armR:{r:38 * k * b}},
        {tailL:{r:4 * k}, tailR:{r:-4 * k}},
        legs(3 * k, -18 * k, 0, 22 * k))};
    },
    bow(t){
      const k = ease(t / .7) * (t > 1.2 ? 1 - ease((t - 1.2) / .6) : 1);
      return {root:{dy:10 * k}, p:merge(
        {torso:{r:7 * k, sy:1 - .035 * k}, head:{r:10 * k, dy:12 * k}, skirt:{sy:1 - .03 * k}},
        {armL:{r:10 * k}, armR:{r:10 * k}}, legs(0, 0))};
    }
  };
})();

// キュアホイップ：パーツを 関節で 動かす（作成・再生の 入口）
window.WhipCharacter = {
  show(wrap, seq){
    const st = document.createElement('div'); st.className = 'wh-stage';
    const inn = document.createElement('div'); inn.className = 'wh-inner';
    st.append(inn); wrap.append(st);
    const rig = WhipRig.create(PARTS, inn);
    const M = WhipMotions, t0 = performance.now();
    const frame = now => {
      if(!st.isConnected) return;                  // 表示が 終わったら 止まる
      const H = wrap.clientHeight || 1, W = wrap.clientWidth || 1, s = H / 1045;
      inn.style.transform = `translateX(${(W - 540 * s) / 2}px) scale(${s})`;
      let el = (now - t0) / 1000, name = 'idle', lt = el;
      for(const [n, dur] of seq){ if(el < dur){ name = n; break; } el -= dur; lt = el; }
      const f = M[name](lt);
      rig.setRoot(f.root); rig.set(f.p);
      requestAnimationFrame(frame);
    };
    requestAnimationFrame(frame);
    return st;
  }
};

})();
